-- A whole number in range; CASE so a string returns false, not a cast error.
create or replace function pg_temp.contract_whole(p jsonb,p_min numeric,p_max numeric) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='number'
    then (p::text)::numeric=trunc((p::text)::numeric) and (p::text)::numeric between p_min and p_max
    else false end;
$$;

create or replace function pg_temp.contract_str_in(p jsonb,p_list jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p)='string' and p_list ? (p#>>'{}'),false);
$$;

-- A non-empty array of distinct strings drawn from p_list.
create or replace function pg_temp.contract_subset(p jsonb,p_list jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='array' then jsonb_array_length(p)>0
    and not exists(select 1 from jsonb_array_elements(p) e where not pg_temp.contract_str_in(e,p_list))
    and (select count(distinct e) from jsonb_array_elements(p) e)=jsonb_array_length(p)
    else false end;
$$;

create or replace function pg_temp.contract_date(p jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p)='string'
    and (p#>>'{}') ~ (pg_temp.parking_contract()->'date'->>'pattern')
    and pg_input_is_valid(p#>>'{}','date'),false);
$$;

-- days, from and to of a schedule slot or a fee period; leaving out both
-- from and to means all day.
create or replace function pg_temp.contract_slot_times(p jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(case when jsonb_typeof(p->'days')='string'
      then pg_temp.contract_str_in(p->'days',pg_temp.parking_contract()->'time'->'days')
      else pg_temp.contract_subset(p->'days',pg_temp.parking_contract()->'time'->'weekdays') end
    and (not p ?| array(select jsonb_array_elements_text(pg_temp.parking_contract()->'time'->'optional_pair'))
    or jsonb_typeof(p->'from')='string' and jsonb_typeof(p->'to')='string'
    and (p->>'from') ~ (pg_temp.parking_contract()->'time'->>'pattern')
    and (p->>'to') ~ (pg_temp.parking_contract()->'time'->>'pattern')
    and p->>'from'<>p->>'to'),false);
$$;

-- An object with only the listed keys, and all of them except the optional
-- from/to pair, which contract_slot_times checks.
create or replace function pg_temp.contract_slot_keys(p jsonb,p_keys jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='object' then
    not exists(select 1 from jsonb_object_keys(p) k where not p_keys ? k)
    and not exists(select 1 from jsonb_array_elements_text(p_keys) k
      where not p ? k and not pg_temp.parking_contract()->'time'->'optional_pair' ? k)
    else false end;
$$;

-- ===== 停放條件：valid_condition()、condition_space_type()（C2 複製本段與共用段） =====

-- A bay's or a zone's condition (§1.2, §4.3), the same rules as
-- validCondition in validate.ts and lib/models/parking_condition.dart.
create or replace function pg_temp.valid_condition(p_condition jsonb,p_zone boolean default false) returns boolean
language plpgsql immutable set search_path='' as $$
declare
  p jsonb:=p_condition;
  c jsonb:=pg_temp.parking_contract()->'condition';
  l jsonb; v jsonb; spec jsonb; f record; kinds text[]:='{}';
begin
  if jsonb_typeof(p) is distinct from 'object' or p='{}'::jsonb then return false; end if;
  if exists(select 1 from jsonb_object_keys(p) k
      where not (c->'keys' ? k or (p_zone and c->'zone_keys' ? k))) then return false; end if;
  if (p ? 'bay' and not pg_temp.contract_str_in(p->'bay',c->'bay'))
    or (p ? 'use' and not pg_temp.contract_str_in(p->'use',c->'use'))
    or (p ? 'share' and not (jsonb_typeof(p->'share')='string' and c->'share' ? (p->>'share')))
    or (p ? 'charge' and not pg_temp.contract_str_in(p->'charge',c->'charge')) then return false; end if;
  if not p_zone and not p ? 'bay' then return false; end if;
  if (p ? 'share')<>coalesce(p->>'use'='share',false) then return false; end if;
  if p ? 'share' and (p->>'bay') is distinct from (c->'share'->>(p->>'share')) then return false; end if;

  if p ? 'limits' then
    if jsonb_typeof(p->'limits') is distinct from 'array'
      or jsonb_array_length(p->'limits') not between 1 and (select count(*) from jsonb_object_keys(c->'limits'))
    then return false; end if;
    for l in select e from jsonb_array_elements(p->'limits') e loop
      if jsonb_typeof(l) is distinct from 'object' or jsonb_typeof(l->'kind') is distinct from 'string'
        or not c->'limits' ? (l->>'kind') or (l->>'kind')=any(kinds) then return false; end if;
      kinds:=kinds||(l->>'kind');
      spec:=c->'limits'->(l->>'kind');
      for f in select key,value from jsonb_each(l) loop
        continue when f.key='kind' or spec->'required' ? f.key;
        if not spec->'optional' ? f.key or not pg_temp.contract_whole(f.value,
            (spec->'optional'->f.key->>'min')::numeric,(spec->'optional'->f.key->>'max')::numeric)
        then return false; end if;
      end loop;
      if exists(select 1 from jsonb_array_elements_text(spec->'required') r where not l ? r) then return false; end if;
      if l ? 'vehicle' and not pg_temp.contract_str_in(l->'vehicle',c->'special_vehicles') then return false; end if;
    end loop;
  end if;
  if not p_zone and p->>'bay'='motorcycle' and not p ? 'charge'
    and not kinds && array(select jsonb_array_elements_text(c->'street_charge_optional_with'))
  then return false; end if;

  if p ? 'allow' then
    v:=p->'allow';
    if jsonb_typeof(v) is distinct from 'object' or v='{}'::jsonb
      or exists(select 1 from jsonb_each(v) e where not c->'allow_keys' ? e.key or jsonb_typeof(e.value)<>'boolean')
    then return false; end if;
    if v->'scooter'='true'::jsonb and p->>'bay'='heavy' then return false; end if;
  end if;

  if p ? 'schedule' then
    if jsonb_typeof(p->'schedule') is distinct from 'array'
      or jsonb_array_length(p->'schedule') not between 1 and (c->'schedule'->>'max_entries')::integer
    then return false; end if;
    for l in select e from jsonb_array_elements(p->'schedule') e loop
      if not pg_temp.contract_slot_keys(l,c->'schedule'->'keys') or not pg_temp.contract_slot_times(l)
        or not pg_temp.contract_subset(l->'vehicles',c->'schedule'->'vehicles') then return false; end if;
    end loop;
  end if;

  if p ? 'basis' then
    v:=p->'basis';
    if jsonb_typeof(v) is distinct from 'object'
      or exists(select 1 from jsonb_object_keys(v) k where not c->'basis'->'keys' ? k) then return false; end if;
    -- Reserved until photo evidence ships (verification plan P2).
    if exists(select 1 from jsonb_array_elements_text(c->'basis'->'reserved') r
        where coalesce(jsonb_typeof(v->r),'null')<>'null') then return false; end if;
    if not exists(select 1 from jsonb_array_elements_text(c->'basis'->'required_one_of') r
        where coalesce(jsonb_typeof(v->r),'null')<>'null') then return false; end if;
    if v ? 'source_url' and not coalesce(jsonb_typeof(v->'source_url')='string'
        -- UTF-16 code units, as Dart and JS count: characters outside the BMP count twice.
        and char_length(v->>'source_url')+regexp_count(v->>'source_url','[\U00010000-\U0010FFFF]')
          <=(c->'basis'->'source_url'->>'max_length')::integer
        and (v->>'source_url') ~ (c->'basis'->'source_url'->>'pattern'),false) then return false; end if;
    if (coalesce(jsonb_typeof(v->'effective_date'),'null')<>'null' and not pg_temp.contract_date(v->'effective_date'))
      or (coalesce(jsonb_typeof(v->'expires_on'),'null')<>'null' and not pg_temp.contract_date(v->'expires_on'))
    then return false; end if;
    if jsonb_typeof(v->'effective_date')='string' and jsonb_typeof(v->'expires_on')='string'
      and (v->>'expires_on') collate "C"<=(v->>'effective_date') collate "C" then return false; end if;
  end if;
  return true;
end;
$$;

-- The legacy space_type a condition is stored under (§1.3): the first
-- to_space_type rule that matches, or null.
create or replace function pg_temp.condition_space_type(p_condition jsonb,p_off_street boolean) returns text
language plpgsql immutable set search_path='' as $$
declare p jsonb:=p_condition; r jsonb; w jsonb;
begin
  for r in select e from jsonb_array_elements(pg_temp.parking_contract()->'conversion'->'to_space_type') e loop
    w:=r->'when';
    if (not w ? 'placement' or p_off_street)
      and (not w ? 'limit' or exists(select 1 from jsonb_array_elements(
        case when jsonb_typeof(p->'limits')='array' then p->'limits' else '[]'::jsonb end) l
        where l->>'kind'=w->>'limit'))
      and (not w ? 'share' or p->>'share' is not distinct from w->>'share')
      and (not w ? 'bay' or p->>'bay' is not distinct from w->>'bay')
      and (not w ? 'charge' or p->>'charge' is not distinct from w->>'charge')
    then return r->>'space_type'; end if;
  end loop;
  return null;
end;
$$;

-- Whether a spot is off the street (§1.1 placement); never stored.
create or replace function pg_temp.condition_off_street(p_space_type text,p_facility_type text) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(pg_temp.parking_contract()->'placement'->'off_street_space_types' ? p_space_type,false)
    or coalesce(pg_temp.parking_contract()->'placement'->'off_street_facility_types' ? p_facility_type,false);
$$;

-- The legacy access a zone condition is written back as (§1.3, to_access):
-- the from_access entry with the same allow and, when the entry names a bay,
-- the same bay; null when none matches. At most one entry can match.
create or replace function pg_temp.condition_legacy_access(p_condition jsonb) returns text
language sql immutable set search_path='' as $$
  select min(a.key) from jsonb_each(pg_temp.parking_contract()->'conversion'->'from_access') a
  where jsonb_typeof(p_condition->'allow')='object'
    and (a.value->'allow'->'scooter') is not distinct from (p_condition->'allow'->'scooter')
    and (a.value->'allow'->'heavy') is not distinct from (p_condition->'allow'->'heavy')
    and (not a.value ? 'bay' or (a.value->'bay') is not distinct from (p_condition->'bay'));
$$;

-- legacySafe (§1.3, conversion.legacy_safe): whether old apps, reading only
-- the legacy space_type (a street condition) or access (p_zone), see the
-- same condition or a more conservative one. Converts and reads back, then
-- compares, losing only (a) scooter_heavy read back as usual, (b) a basis
-- without the unsafe keys, (c) the lossy limit keys and (d) facets the read
-- back leaves unconfirmed, except a charge old apps assume. Null is safe.
create or replace function pg_temp.condition_legacy_safe(p_condition jsonb,p_zone boolean default false) returns boolean
language plpgsql immutable set search_path='' as $$
declare
  conv jsonb:=pg_temp.parking_contract()->'conversion';
  r jsonb:=conv->'legacy_safe';
  o jsonb:=p_condition; b jsonb; t text; k text;
  lossy text[]:=array(select jsonb_array_elements_text(r->'lossy_limit_keys'));
begin
  if o is null or jsonb_typeof(o)='null' then return true; end if;
  if p_zone then
    t:=pg_temp.condition_legacy_access(o);
    b:=conv->'from_access'->t;
  else
    t:=pg_temp.condition_space_type(o,false);
    b:=conv->'from_space_type'->t;
  end if;
  if b is null or jsonb_typeof(b)<>'object' then return false; end if;
  if o ?| array(select jsonb_array_elements_text(r->'unsafe_keys')) then return false; end if;
  -- (b) a basis without the unsafe keys; a null value counts as left out.
  if exists(select 1 from jsonb_array_elements_text(r->'unsafe_basis_keys') x
      where coalesce(jsonb_typeof(o->'basis'->x),'null')<>'null') then return false; end if;
  o:=o-'basis'; b:=b-'basis';
  -- (c) limit keys old apps never read.
  if jsonb_typeof(o->'limits')='array' then
    o:=jsonb_set(o,'{limits}',(select jsonb_agg(e-lossy) from jsonb_array_elements(o->'limits') e));
  end if;
  if jsonb_typeof(b->'limits')='array' then
    b:=jsonb_set(b,'{limits}',(select jsonb_agg(e-lossy) from jsonb_array_elements(b->'limits') e));
  end if;
  -- (a) a shared use read back as usual.
  if o->>'share'=r->>'lossy_share' and b->>'use'='usual' and not b ? 'share' then
    o:=(o-'share')||'{"use":"usual"}'::jsonb;
  end if;
  -- (d) facets the legacy value leaves unconfirmed, except an assumed charge.
  if not p_zone and r->'assumed_charge' ? t and not b ? 'charge' and o ? 'charge'
    and o->>'charge'<>r->'assumed_charge'->>t then return false; end if;
  for k in select jsonb_array_elements_text(r->'lossy_when_unconfirmed') loop
    if not b ? k then o:=o-k; end if;
  end loop;
  return o=b;
end;
$$;

-- Whether old builds, which read a zone's access only, read a stored zone
-- (an element of parking_zones) as it is: it has no condition, or a
-- legacy-safe one stored with the access it writes back.
create or replace function pg_temp.zone_legacy_safe(p_zone jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p_zone->'condition'),'null')='null'
    or (pg_temp.condition_legacy_safe(p_zone->'condition',true)
      and (p_zone->>'access') is not distinct from pg_temp.condition_legacy_access(p_zone->'condition'));
$$;

-- Whether a zone's access agrees with its condition (§1.3, decision 32): a
-- zone without a condition is not checked here; one with a condition has an
-- allow naming both vehicles, and its access is the one the condition writes
-- back. A condition that writes back no access is inconsistent.
create or replace function pg_temp.zone_condition_consistent(p_zone jsonb) returns boolean
language sql immutable set search_path='' as $$
  select coalesce(jsonb_typeof(p_zone->'condition'),'null')='null'
    or (jsonb_typeof(p_zone->'access')='string'
      and coalesce((p_zone->>'access')=pg_temp.condition_legacy_access(p_zone->'condition'),false));
$$;

-- Whether a whole spot is legacy-safe: a street spot by its condition, a lot
-- only without a top-level condition and when every zone is.
create or replace function pg_temp.condition_legacy_safe_spot(p_off_street boolean,p_condition jsonb,p_zones jsonb) returns boolean
language sql immutable set search_path='' as $$
  select case when p_off_street then coalesce(jsonb_typeof(p_condition),'null')='null'
      and not exists(select 1 from jsonb_array_elements(
        case when jsonb_typeof(p_zones)='array' then p_zones else '[]'::jsonb end) z
        where not pg_temp.zone_legacy_safe(z))
    else pg_temp.condition_legacy_safe(p_condition,false) end;
$$;

-- ===== 費率 v2：valid_fee(p_fee)（只屬於 C3；C2 不可複製，否則會提早換掉現行的費率檢查） =====

-- The keys of p (besides mode) against a {required, optional} spec: ranges
-- (max may name a sibling key), enums, extension and periods.
create or replace function pg_temp.contract_fee_fields(p jsonb,p_spec jsonb,p_vehicle text) returns boolean
language plpgsql immutable set search_path='' as $$
declare fee jsonb:=pg_temp.parking_contract()->'fee'; f record; fs jsonb; hi numeric;
begin
  if jsonb_typeof(p) is distinct from 'object' then return false; end if;
  for f in select key,value from jsonb_each(p) loop
    continue when f.key='mode';
    fs:=coalesce(p_spec->'required'->f.key,p_spec->'optional'->f.key);
    if fs is null then return false; end if;
    if jsonb_typeof(fs)='object' then
      if jsonb_typeof(fs->'max')='string' then
        hi:=case when pg_temp.contract_whole(p->(fs->>'max'),0,1e9) then (p->>(fs->>'max'))::numeric end;
        if hi is null then return false; end if;
      else hi:=(fs->>'max')::numeric; end if;
      if not pg_temp.contract_whole(f.value,(fs->>'min')::numeric,hi) then return false; end if;
    elsif fee->'enums' ? (fs#>>'{}') then
      if not pg_temp.contract_str_in(f.value,fee->'enums'->(fs#>>'{}')) then return false; end if;
    elsif fs#>>'{}'='extension' then
      if jsonb_typeof(f.value) is distinct from 'object' or (f.value ? 'mode')
        or not pg_temp.contract_fee_fields(f.value,fee->'extension',p_vehicle) then return false; end if;
    elsif fs#>>'{}'='periods' then
      if jsonb_typeof(f.value) is distinct from 'array'
        or jsonb_array_length(f.value) not between 1 and (fee->'periods'->>'max_entries')::integer
        or exists(select 1 from jsonb_array_elements(f.value) e
          where not pg_temp.contract_slot_keys(e,fee->'periods'->'keys') or not pg_temp.contract_slot_times(e)
            or not pg_temp.contract_fee_rate(e->'rate',p_vehicle,true))
      then return false; end if;
    else return false; end if;
  end loop;
  return not exists(select 1 from jsonb_object_keys(p_spec->'required') r where not p ? r);
end;
$$;

-- One vehicle's rate (§2.2); a period's rate may not follow or nest by_time.
create or replace function pg_temp.contract_fee_rate(p jsonb,p_vehicle text,p_nested boolean) returns boolean
language plpgsql immutable set search_path='' as $$
declare fee jsonb:=pg_temp.parking_contract()->'fee'; m text;
begin
  if jsonb_typeof(p) is distinct from 'object' or jsonb_typeof(p->'mode') is distinct from 'string' then return false; end if;
  m:=p->>'mode';
  if fee->'follow'->'modes' ? m then
    return not p_nested and fee->'follow'->'vehicles' ? p_vehicle
      and pg_temp.contract_fee_fields(p,jsonb_build_object('required','{}'::jsonb,'optional',fee->'follow'->'optional'),p_vehicle);
  end if;
  if not fee->'modes' ? m or (p_nested and not fee->'periods'->'nested_modes' ? m) then return false; end if;
  return pg_temp.contract_fee_fields(p,fee->'modes'->m,p_vehicle);
end;
$$;

-- Fee v2 (§2.2): a rate per vehicle; a missing vehicle is unconfirmed.
create or replace function pg_temp.valid_fee(p_fee jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare fee jsonb:=pg_temp.parking_contract()->'fee'; p jsonb:=p_fee;
begin
  if jsonb_typeof(p) is distinct from 'object' then return false; end if;
  return pg_column_size(p)<=(fee->>'max_bytes')::integer
    and not exists(select 1 from jsonb_object_keys(p) k where not fee->'vehicles' ? k)
    and not exists(select 1 from jsonb_object_keys(p) k where not pg_temp.contract_fee_rate(p->k,k,false));
end;
$$;

-- ===== 費率文字：fee_note_of(p_fee)（C3；與 tool/fee_text.py、lib/models/fee.dart、
-- supabase/functions/_shared/fee.ts 同一套句子，parking_contract_cases.json 的 fee_notes 固定） =====

-- Whole yuan times a factor in percent, with at most two decimals: 22.5, 41.25.
create or replace function pg_temp.fee_text_money(p jsonb,p_pct integer) returns text
language sql immutable set search_path='' as $$
  select case when v%100=0 then (v/100)::text
    when v%10=0 then (v/100)::text||'.'||(v%100/10)::text
    else (v/100)::text||'.'||lpad((v%100)::text,2,'0') end
  from (select (p#>>'{}')::numeric::bigint*p_pct as v) x;
$$;

-- 3 小時, 45 分鐘.
create or replace function pg_temp.fee_text_span(p jsonb) returns text
language sql immutable set search_path='' as $$
  select case when m%60=0 then (m/60)||' 小時' else m||' 分鐘' end
  from (select (p#>>'{}')::numeric::integer as m) x;
$$;

-- 每小時, 每 2 小時, 每 90 分鐘.
create or replace function pg_temp.fee_text_every(p jsonb) returns text
language sql immutable set search_path='' as $$
  select case when m=60 then '每小時' when m%60=0 then '每 '||(m/60)||' 小時' else '每 '||m||' 分鐘' end
  from (select (p#>>'{}')::numeric::integer as m) x;
$$;

-- When a cap or a daily charge starts over; null when unconfirmed.
create or replace function pg_temp.fee_text_reset(p text) returns text
language sql immutable set search_path='' as $$
  select case p when 'calendar_day' then '零時重算' when 'rolling_24h' then '停滿 24 小時重算'
    when 'per_entry' then '每次進場重算' end;
$$;

-- A set of days as a bit mask (bit 0 Monday) and its label.
create or replace function pg_temp.fee_text_day_mask(p jsonb) returns integer
language sql immutable set search_path='' as $$
  select case when jsonb_typeof(p)='string' then case p#>>'{}' when 'all' then 127 when 'weekday' then 31 else 96 end
    else (select sum(1<<(array_position(array['mon','tue','wed','thu','fri','sat','sun'],d)-1))::integer
      from jsonb_array_elements_text(p) d) end;
$$;

create or replace function pg_temp.fee_text_days(p_mask integer) returns text
language sql immutable set search_path='' as $$
  select case p_mask when 127 then '每天' when 31 then '平日' when 96 then '假日'
    else (select string_agg('週'||substr('一二三四五六日',i+1,1),'、' order by i)
      from generate_series(0,6) i where p_mask&(1<<i)<>0) end;
$$;

-- One rate's words at p_pct percent of its amounts, or null when it reads
-- as unconfirmed (posted, a by_time of posted periods only, a follow).
create or replace function pg_temp.fee_text_rate(p jsonb,p_pct integer) returns text
language plpgsql immutable set search_path='' as $$
declare
  m text:=p->>'mode'; t text; notes text[]; e jsonb; mask integer; i integer;
  masks integer[]:='{}'; parts text[]:='{}'; visits integer:=0;
begin
  if jsonb_typeof(p) is distinct from 'object' then return null; end if;
  if m='free' then return '免費'; end if;
  if m='hourly' then
    t:=pg_temp.fee_text_every(p->'per_minutes')||' '||pg_temp.fee_text_money(p->'amount',p_pct)||' 元';
    if p ? 'free_minutes' then t:='首 '||pg_temp.fee_text_span(p->'free_minutes')||' 0 元，之後'||t; end if;
    if p ? 'unit_minutes' then t:=t||'（以 '||pg_temp.fee_text_span(p->'unit_minutes')||'計）'; end if;
    if p ? 'daily_cap' then
      t:=t||'，當日上限 '||pg_temp.fee_text_money(p->'daily_cap',p_pct)||' 元（'
        ||coalesce(pg_temp.fee_text_reset(p->>'cap_reset'),'上限計算方式未確認')||'）';
    end if;
    return t;
  end if;
  if m='per_visit' then
    if (p->>'amount')::numeric=0 and p ? 'max_minutes' then
      t:='首 '||pg_temp.fee_text_span(p->'max_minutes')||' 0 元';
    else
      notes:='{}';
      if p ? 'max_minutes' then notes:=notes||(pg_temp.fee_text_span(p->'max_minutes')||'內'); end if;
      if not p ? 'renew' then notes:=notes||'隔日是否另計未確認'::text; end if;
      t:='每次 '||pg_temp.fee_text_money(p->'amount',p_pct)||' 元'
        ||case when cardinality(notes)>0 then '（'||array_to_string(notes,'，')||'）' else '' end
        ||case p->>'renew' when 'midnight' then '，隔日另計'
          when 'none' then case when p ? 'max_minutes' then '，有效時間內只收一次' else '，停多久都只收一次' end
          else '' end;
    end if;
    if jsonb_typeof(p->'extension')='object' then
      t:=t||'，可付 '||pg_temp.fee_text_money(p->'extension'->'amount',p_pct)||' 元延長 '
        ||(p->'extension'->>'max_times')::numeric::integer||' 次'
        ||case when p->'extension' ? 'minutes' then '（每次 '||pg_temp.fee_text_span(p->'extension'->'minutes')||'）'
          else '（延長時間未確認）' end;
    end if;
    return t;
  end if;
  if m='daily' then
    return '每日 '||pg_temp.fee_text_money(p->'amount',p_pct)||' 元'||coalesce('（'||pg_temp.fee_text_reset(p->>'cap_reset')||'）','');
  end if;
  if m='by_time' then
    -- Periods grouped by the days they cover, in order of first appearance.
    for e in select x from jsonb_array_elements(p->'periods') x loop
      t:=pg_temp.fee_text_rate(e->'rate',p_pct);
      continue when t is null;
      if e->'rate'->>'mode'='per_visit' then visits:=visits+1; end if;
      t:=case when e ? 'from' then (e->>'from')||'–'
          ||case when (e->>'from') collate "C"<(e->>'to') collate "C" then '' else '隔日 ' end||(e->>'to')
        else '全天' end||' '||t;
      mask:=pg_temp.fee_text_day_mask(e->'days');
      i:=array_position(masks,mask);
      if i is null then masks:=masks||mask; parts:=parts||t; else parts[i]:=parts[i]||'；'||t; end if;
    end loop;
    if cardinality(masks)=0 then return null; end if;
    t:=(select string_agg(pg_temp.fee_text_days(masks[k])||'：'||parts[k],'；' order by k)
      from generate_subscripts(masks,1) k);
    if p ? 'cross_period' then
      t:=t||'；'||case p->>'cross_period' when 'each_period' then '跨時段分別計費' else '依進場時段計費' end;
    elsif visits>=2 then t:=t||'；跨時段計費方式未確認';
    end if;
    return t;
  end if;
  return null;
end;
$$;

-- The fee_note text of a valid fee: known vehicles as 機車…；大型重機…；汽車…,
-- then 大型重機費率未確認 when the heavy rate is unknown; a heavy rate that
-- follows another vehicle shows the amounts worked out (#140), or
-- 大型重機費率未提供 when that vehicle is unconfirmed.
create or replace function pg_temp.fee_note_of(p_fee jsonb) returns text
language plpgsql immutable set search_path='' as $$
declare
  f text:=p_fee->'heavy'->>'mode'; s text; h text; c text; unprovided boolean:=false; parts text[]:='{}';
begin
  s:=pg_temp.fee_text_rate(p_fee->'scooter',100);
  c:=pg_temp.fee_text_rate(p_fee->'car',100);
  if f in ('same_as_scooter','same_as_car') then
    h:=pg_temp.fee_text_rate(p_fee->(case f when 'same_as_scooter' then 'scooter' else 'car' end),
      coalesce((p_fee->'heavy'->>'factor_pct')::numeric::integer,100));
    unprovided:=h is null;
  else
    h:=pg_temp.fee_text_rate(p_fee->'heavy',100);
  end if;
  if s is null and h is null and c is null and not unprovided then return '請依現場公告'; end if;
  if s is not null then parts:=parts||('機車'||s); end if;
  if h is not null or unprovided then parts:=parts||('大型重機'||coalesce(h,'費率未提供')); end if;
  if c is not null then parts:=parts||('汽車'||c); end if;
  if h is null and not unprovided then parts:=parts||'大型重機費率未確認'::text; end if;
  return array_to_string(parts,'；');
end;
$$;

-- ===== 計費規則：valid_fee_plans()（C3 第二層，§2.6） =====

-- A spot's fee plans, its own plan reference and its zones' (§2.6): at
-- most max_entries plans of {id, name, fee}, ids unique and of id_pattern,
-- names of 1–name_max_length UTF-16 code units, each fee a valid, non-empty
-- fee. Every reference names an existing plan, and a spot or zone that
-- refers to one carries that plan's fee as its own copy for older builds.
create or replace function pg_temp.valid_fee_plans(p_plans jsonb,p_fee_plan text,p_fee jsonb,p_zones jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare c jsonb:=pg_temp.parking_contract()->'fee_plans'; p jsonb; z jsonb; ids text[]:='{}';
begin
  if coalesce(jsonb_typeof(p_plans),'null')<>'null' then
    if jsonb_typeof(p_plans)<>'array'
      or jsonb_array_length(p_plans) not between 1 and (c->>'max_entries')::integer then return false; end if;
    for p in select e from jsonb_array_elements(p_plans) e loop
      if jsonb_typeof(p) is distinct from 'object'
        or exists(select 1 from jsonb_object_keys(p) k where not c->'keys' ? k)
        or exists(select 1 from jsonb_array_elements_text(c->'keys') k where not p ? k)
        or jsonb_typeof(p->'id') is distinct from 'string' or (p->>'id') !~ (c->>'id_pattern') or (p->>'id')=any(ids)
        or jsonb_typeof(p->'name') is distinct from 'string' or btrim(p->>'name')=''
        -- UTF-16 code units, as Dart and JS count.
        or char_length(p->>'name')+regexp_count(p->>'name','[\U00010000-\U0010FFFF]')>(c->>'name_max_length')::integer
        or not pg_temp.valid_fee(p->'fee') or p->'fee'='{}'::jsonb then return false; end if;
      ids:=ids||(p->>'id');
    end loop;
  end if;
  if p_fee_plan is not null and (not p_fee_plan=any(ids) or p_fee is distinct from
      (select e->'fee' from jsonb_array_elements(p_plans) e where e->>'id'=p_fee_plan)) then return false; end if;
  for z in select e from jsonb_array_elements(case when jsonb_typeof(p_zones)='array' then p_zones else '[]'::jsonb end) e loop
    continue when jsonb_typeof(z) is distinct from 'object' or not z ? 'fee_plan';
    if jsonb_typeof(z->'fee_plan') is distinct from 'string' or not (z->>'fee_plan')=any(ids)
      or (z->'fee') is distinct from (select e->'fee' from jsonb_array_elements(p_plans) e where e->>'id'=z->>'fee_plan')
    then return false; end if;
  end loop;
  return true;
end;
$$;

-- The longest fee_note_of() the contract allows (§2.5), worked out by
-- tool/fee_text.py: the bound of both spot tables' fee_note check and of
-- validate.ts for a note that is its fee's text.
create or replace function pg_temp.fee_note_max_length() returns integer
language sql immutable set search_path='' as $$
  select 1909;
$$;

